// Every field that only some statuses have is optional,
// so impossible states (shipped with no tracking number…) compile.
type Order = {
  id: number;
  status: 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';
  trackingNumber?: string; // shipped, delivered, returned
  deliveredAt?: string;    // delivered, returned
  cancelReason?: string;   // cancelled
  refundCents?: number;    // returned
};

function ship(order: Order, trackingNumber: string): Order {
  return { id: order.id, status: 'shipped', trackingNumber };
}

function describe(order: Order): string {
  switch (order.status) {
    case 'processing': return `#${order.id} is being packed`;
    case 'shipped': return `#${order.id} is on its way (${order.trackingNumber})`;
    case 'delivered': return `#${order.id} arrived on ${order.deliveredAt}`;
    case 'cancelled': return `#${order.id} was cancelled: ${order.cancelReason}`;
    case 'returned': return `#${order.id} was refunded $${(order.refundCents! / 100).toFixed(2)}`;
  }
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<Order['status'], 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned'>>;

// @ts-expect-error: a shipped order must have a tracking number
const noTracking: Order = { id: 1, status: 'shipped' };

// @ts-expect-error: a cancelled order cannot have a delivery date
const cancelledButDelivered: Order = { id: 2, status: 'cancelled', cancelReason: 'Out of stock', deliveredAt: '2025-05-02' };

// @ts-expect-error: only processing orders can be shipped
ship({ id: 3, status: 'delivered', trackingNumber: '1Z-77', deliveredAt: '2025-05-02' }, '1Z-88');

console.log(describe(ship({ id: 1042, status: 'processing' }, '1Z-999')));

